package fr.roadguard.app;
import android.app.Application;import android.speech.tts.TextToSpeech;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={27,28},application=Application.class) @LooperMode(LooperMode.Mode.PAUSED)
public class OverspeedSpeechRuntimeTest {
 Application app;TextToSpeech tts;
 @Before public void setup(){app=RuntimeEnvironment.getApplication();app.getSharedPreferences("MainActivity",0).edit().clear().commit();app.getSharedPreferences("roadguard_radar_audio",0).edit().clear().commit();tts=new TextToSpeech(app,status->{});}
 @After public void close(){tts.shutdown();}
 AlertSpeechTracker tracker(){return new AlertSpeechTracker(app,(task,delay)->()->{});}
 @Test public void warningRequiresKnownLimitSpeedAndNearbyRadar(){assertTrue(OverspeedSpeech.eligible(500,91,90));assertFalse(OverspeedSpeech.eligible(1001,100,90));assertFalse(OverspeedSpeech.eligible(-1,100,90));assertFalse(OverspeedSpeech.eligible(500,90,90));assertFalse(OverspeedSpeech.eligible(500,100,0));assertFalse(OverspeedSpeech.eligible(Double.NaN,100,90));assertFalse(OverspeedSpeech.eligible(500,Double.NaN,90));}
 @Test public void voiceSwitchesAreRespected(){AlertSpeechTracker t=tracker();app.getSharedPreferences("MainActivity",0).edit().putBoolean("overspeed_voice",false).commit();assertFalse(OverspeedSpeech.warn(app,t,tts,true,500,100,90,100000));app.getSharedPreferences("MainActivity",0).edit().putBoolean("overspeed_voice",true).putBoolean("Alertes vocales",false).commit();assertFalse(OverspeedSpeech.warn(app,t,tts,true,500,100,90,100000));assertEquals(0,app.getSharedPreferences("roadguard_radar_audio",0).getLong("overspeed_spoken_at",0));}
 @Test public void deniedAudioDoesNotConsumeWarning(){AlertSpeechTracker t=tracker();t.useAudio(new AlertSpeechTracker.Audio(){public boolean acquire(String id,int p,Runnable r){return false;}public void release(String id){}public void cancel(String id){}});assertFalse(OverspeedSpeech.warn(app,t,tts,true,500,100,90,100000));assertEquals(0,app.getSharedPreferences("roadguard_radar_audio",0).getLong("overspeed_spoken_at",0));}
 @Test public void foregroundAndBackgroundShareThirtySecondCooldown(){AlertSpeechTracker first=tracker(),second=tracker(),third=tracker();assertTrue(OverspeedSpeech.warn(app,first,tts,true,500,100,90,100000));assertEquals(100000,app.getSharedPreferences("roadguard_radar_audio",0).getLong("overspeed_spoken_at",0));assertFalse(OverspeedSpeech.warn(app,second,tts,true,400,100,90,110000));assertTrue(OverspeedSpeech.warn(app,third,tts,true,300,100,90,130001));third.cancelAll();assertEquals(0,app.getSharedPreferences("roadguard_radar_audio",0).getLong("overspeed_spoken_at",0));first.cancelAll();}
}
